CREATE TABLE public.document_types (
    id uuid DEFAULT app.uuidv7() NOT NULL,
    code text NOT NULL,
    label text NOT NULL,
    requires_expiry boolean DEFAULT false NOT NULL,
    retention_class text DEFAULT 'operational'::text NOT NULL,
    is_special_category boolean DEFAULT false NOT NULL,
    is_active boolean DEFAULT true NOT NULL,
    sort_order smallint DEFAULT 100 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    deleted_at timestamp with time zone,
    version integer DEFAULT 1 NOT NULL
);


--

--

COMMENT ON TABLE public.document_types IS 'Lookup table, not an enum. The acceptable document set is a risk and compliance decision (CANONICAL.md D-04) and changes without a code deploy. is_special_category flags documents that attract heightened obligations under the Nigeria Data Protection Act 2023.';


