CREATE TABLE public.idempotency_keys (
    key text NOT NULL,
    user_id uuid NOT NULL,
    route text NOT NULL,
    method text NOT NULL,
    request_hash bytea NOT NULL,
    state public.idempotency_state DEFAULT 'in_progress'::public.idempotency_state NOT NULL,
    response_status integer,
    response_body jsonb,
    resource_type text,
    resource_id uuid,
    is_retryable boolean DEFAULT false NOT NULL,
    locked_at timestamp with time zone DEFAULT now() NOT NULL,
    completed_at timestamp with time zone,
    expires_at timestamp with time zone NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    deleted_at timestamp with time zone,
    version integer DEFAULT 1 NOT NULL,
    CONSTRAINT idempotency_keys_completed_is_complete CHECK (((state <> 'completed'::public.idempotency_state) OR ((response_status IS NOT NULL) AND (completed_at IS NOT NULL)))),
    CONSTRAINT idempotency_keys_expiry_after_creation CHECK ((expires_at > created_at)),
    CONSTRAINT idempotency_keys_method_check CHECK ((method = ANY (ARRAY['POST'::text, 'PUT'::text, 'PATCH'::text, 'DELETE'::text])))
);


--

--

COMMENT ON TABLE public.idempotency_keys IS 'The retried-request ledger. A replayed POST with the same key and the same body returns the stored response verbatim; the same key with a different body is a 409. See section 9.7 for the algorithm and the TTL.';


