CREATE TABLE public.invitations (
    id uuid DEFAULT app.uuidv7() NOT NULL,
    ajo_id uuid NOT NULL,
    position_id uuid,
    email public.citext NOT NULL,
    token_hash bytea NOT NULL,
    status public.invitation_status DEFAULT 'pending'::public.invitation_status NOT NULL,
    message text,
    invited_by_user_id uuid NOT NULL,
    expires_at timestamp with time zone NOT NULL,
    accepted_by_user_id uuid,
    accepted_at timestamp with time zone,
    declined_at timestamp with time zone,
    resend_count smallint DEFAULT 0 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    deleted_at timestamp with time zone,
    version integer DEFAULT 1 NOT NULL,
    CONSTRAINT invitations_accepted_consistent CHECK (((status <> 'accepted'::public.invitation_status) OR ((accepted_at IS NOT NULL) AND (accepted_by_user_id IS NOT NULL)))),
    CONSTRAINT invitations_resend_count_check CHECK ((resend_count >= 0))
);


--

--

COMMENT ON COLUMN public.invitations.token_hash IS 'SHA-256 of the invitation token. The plaintext is in the email only and is never stored, logged or returned by an API. GET /invitations/:token looks the row up by this hash.';


