CREATE TABLE public.notification_preferences (
    id uuid DEFAULT app.uuidv7() NOT NULL,
    user_id uuid NOT NULL,
    push_enabled boolean DEFAULT true NOT NULL,
    email_enabled boolean DEFAULT true NOT NULL,
    sms_enabled boolean DEFAULT true NOT NULL,
    money_sms_opt_in boolean DEFAULT true NOT NULL,
    quiet_hours_start time without time zone,
    quiet_hours_end time without time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    deleted_at timestamp with time zone,
    version integer DEFAULT 1 NOT NULL,
    CONSTRAINT notification_preferences_money_sms_consistent CHECK (((money_sms_opt_in = false) OR (sms_enabled = true))),
    CONSTRAINT notification_preferences_quiet_hours_paired CHECK (((quiet_hours_start IS NULL) = (quiet_hours_end IS NULL)))
);


