    channel public.notification_channel NOT NULL,
    status public.notification_status DEFAULT 'queued'::public.notification_status NOT NULL,
    subject text,
    body text NOT NULL,
    payload jsonb DEFAULT '{}'::jsonb NOT NULL,
    dedupe_key text NOT NULL,
    scheduled_for timestamp with time zone DEFAULT now() NOT NULL,
    sent_at timestamp with time zone,
    delivered_at timestamp with time zone,
    read_at timestamp with time zone,
    failed_at timestamp with time zone,
    failure_detail text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    deleted_at timestamp with time zone,
    version integer DEFAULT 1 NOT NULL,
    amount_kobo bigint,
    fee_kobo bigint,
    CONSTRAINT notifications_amount_kobo_check CHECK (((amount_kobo IS NULL) OR (amount_kobo >= 0))),
    CONSTRAINT notifications_fee_kobo_check CHECK (((fee_kobo IS NULL) OR (fee_kobo >= 0)))
);


--

--

COMMENT ON COLUMN public.notifications.dedupe_key IS 'event_key + the ids that make the event unique, e.g. contribution.received:<contribution_id> or payout.succeeded:<payout_id>. The UNIQUE on (dedupe_key, channel) is what makes a replayed webhook send the receipt once rather than four times.';


