CREATE TABLE public.outbox_events (
    id uuid DEFAULT app.uuidv7() NOT NULL,
    aggregate_type text NOT NULL,
    aggregate_id uuid NOT NULL,
    event_type text NOT NULL,
    payload jsonb NOT NULL,
    status public.outbox_status DEFAULT 'pending'::public.outbox_status NOT NULL,
    attempts smallint DEFAULT 0 NOT NULL,
    next_retry_at timestamp with time zone DEFAULT now() NOT NULL,
    published_at timestamp with time zone,
    last_error text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    version integer DEFAULT 1 NOT NULL,
    CONSTRAINT outbox_events_attempts_check CHECK ((attempts >= 0))
);


--

--

COMMENT ON TABLE public.outbox_events IS 'Written in the SAME transaction as the ledger postings. A payment that posts money and then fails to send its receipt is a member who believes they were not charged; the outbox is the difference between one atomic commit and two hopeful ones. See section 9.3.8 and 9.8.';


